@startuml

class OilWell {
  + code : string
}

abstract class OnshoreWell {
  + surfaceExtension : float
}

abstract class OffshoreWell {
  + installationYear : int
}

class WellCategory {
  + name : string
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

OilWell --|> WellCategory
OnshoreWell --|> OilWell
OffshoreWell --|> OilWell

OilWell "*" -- "*" Company : extracts
Company "*" -- "*" OilWell : extracts

OffshoreWell "0..1" o-- "0..1" GeographicalArea : locatedIn

@enduml

